'use strict';
function receipt({ amount, currency, civilDate, locale, timeZone, name }) {
  const displayCurrency = locale === 'de-DE' ? 'EUR' : currency;
  const amountText = new Intl.NumberFormat(locale, { style: 'currency', currency: displayCurrency }).format(amount);
  const dateText = new Intl.DateTimeFormat(locale, { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(civilDate));
  return { amountText, dateText, name };
}
module.exports = { receipt };

'use strict';
const { messages, pluralLabels } = require('./catalogs.cjs');
function receipt({ amount, currency, civilDate, locale, timeZone, name }) {
  const amountText = new Intl.NumberFormat(locale, { style: 'currency', currency }).format(amount);
  const dateText = new Intl.DateTimeFormat(locale, { timeZone: 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(civilDate + 'T00:00:00Z'));
  return { amountText, dateText, name };
}
function message(locale, key) {
  const selected = Object.hasOwn(messages, locale) ? messages[locale] : null;
  if (selected && Object.hasOwn(selected, key)) return selected[key];
  return Object.hasOwn(messages['en-US'], key) ? messages['en-US'][key] : null;
}
function itemCount(count) {
  const category = new Intl.PluralRules('pl-PL').select(count);
  return `${new Intl.NumberFormat('pl-PL').format(count)} ${pluralLabels[category]}`;
}
module.exports = { receipt, message, itemCount };

