def plan_records(records, tenant, subject, now):
    delete_ids = []
    retain_ids = []
    exported = []
    for row in records:
        if row["tenant"] != tenant or row["subject"] != subject:
            continue
        if row["hold"] or row["expires_at"] > now:
            retain_ids.append(row["id"])
        else:
            delete_ids.append(row["id"])
        exported.append({"id": row["id"], "value": row["value"]})
    return {"delete_ids": delete_ids, "retain_ids": retain_ids, "export": exported}


